import { describe, expect, it } from "vitest";
import {
  compareApiReports,
  diffReports,
  parseReport,
  // @ts-expect-error The scripts are dependency-free JavaScript with JSDoc types.
} from "../../../../scripts/release/apiChanges.mjs";

interface Change {
  kind: string;
  name: string;
  likelyBreaking: boolean;
  detail: string;
}

function report(...blocks: string[]): string {
  return [
    '## API Report File for "@mapcairn/example"',
    "",
    "> Do not edit this file.",
    "",
    "```ts",
    "",
    blocks.join("\n\n"),
    "",
    "// (No @packageDocumentation comment for this package)",
    "",
    "```",
    "",
  ].join("\n");
}

function changes(before: string[], after: string[]): Change[] {
  return diffReports(report(...before), report(...after));
}

const greet = "// @public\nexport function greet(name: string): string;";
const mode = '// @public\nexport type Mode = "light" | "dark";';
const options =
  "// @public\nexport interface Options {\n    label: string;\n    size?: number;\n}";

describe("parseReport", () => {
  it("names each export, including an alias printed with its export line", () => {
    const entries = parseReport(
      report(
        greet,
        "// @public\nconst blur_2: `var(--${string})`;\nexport { blur_2 as blur }",
        "// Warning: (ae-forgotten-export) The symbol needs to be exported\n//\n// @beta\nexport class Store {\n    // (undocumented)\n    open(): void;\n}",
      ),
    );
    expect([...entries.keys()]).toEqual(["greet", "blur", "Store"]);
    expect(entries.get("Store")?.tags).toEqual(["// @beta"]);
    expect(entries.get("Store")?.lines).toEqual([
      "export class Store {",
      "    open(): void;",
      "}",
    ]);
  });

  it("reads nothing from text without a report block", () => {
    expect(parseReport("no report here").size).toBe(0);
  });
});

describe("diffReports", () => {
  it("finds nothing when the reports match", () => {
    expect(changes([greet, mode], [greet, mode])).toEqual([]);
  });

  it("calls a removed export likely breaking", () => {
    expect(changes([greet, mode], [greet])).toEqual([
      expect.objectContaining({
        kind: "removed",
        name: "Mode",
        likelyBreaking: true,
      }),
    ]);
  });

  it("does not call a new export breaking", () => {
    expect(changes([greet], [greet, mode])).toEqual([
      expect.objectContaining({
        kind: "added",
        name: "Mode",
        likelyBreaking: false,
      }),
    ]);
  });

  it("calls a changed or removed line likely breaking", () => {
    const [change] = changes(
      [greet],
      [
        "// @public\nexport function greet(name: string, polite: boolean): string;",
      ],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: true });
    expect(change.detail).toContain("greet(name: string)");
  });

  it("does not call an added member of an interface breaking", () => {
    const [change] = changes(
      [options],
      [
        options.replace(
          "    size?: number;",
          "    size?: number;\n    colour?: string;",
        ),
      ],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: false });
  });

  describe("members a host must now provide", () => {
    const port = "// @public\nexport interface Port {\n    open(): void;\n}";
    const withLine = (line: string) =>
      port.replace("    open(): void;", `    open(): void;\n    ${line}`);

    it.each([
      "close(): void;",
      "label: string;",
      "readonly size: number;",
      "[key: string]: unknown;",
    ])("calls a new required interface member likely breaking: %s", (line) => {
      const [change] = changes([port], [withLine(line)]);
      expect(change).toMatchObject({
        kind: "required-member-added",
        likelyBreaking: true,
      });
      expect(change.detail).toContain(line);
    });

    it.each(["close?(): void;", "label?: string;", "readonly size?: number;"])(
      "does not call a new optional member breaking: %s",
      (line) => {
        expect(changes([port], [withLine(line)])[0]).toMatchObject({
          kind: "changed",
          likelyBreaking: false,
        });
      },
    );

    it("looks at the member, not at the lines of its type", () => {
      const after = withLine("extra?: {\n        needed: string;\n    };");
      expect(changes([port], [after])[0]).toMatchObject({
        likelyBreaking: false,
      });
      const required = withLine("extra: {\n        needed: string;\n    };");
      expect(changes([port], [required])[0]).toMatchObject({
        kind: "required-member-added",
      });
    });

    it("calls a new abstract member of an abstract class likely breaking, and a concrete one not", () => {
      const base =
        "// @public\nexport abstract class Base {\n    abstract run(): void;\n}";
      const abstractMember = base.replace(
        "    abstract run(): void;",
        "    abstract run(): void;\n    protected abstract stop(): void;",
      );
      const concrete = base.replace(
        "    abstract run(): void;",
        "    abstract run(): void;\n    helper(): void;",
      );
      expect(changes([base], [abstractMember])[0]).toMatchObject({
        kind: "required-member-added",
        likelyBreaking: true,
      });
      expect(changes([base], [concrete])[0]).toMatchObject({
        kind: "changed",
        likelyBreaking: false,
      });
    });

    it("does not call a new member of an ordinary class breaking", () => {
      const store = "// @public\nexport class Store {\n    open(): void;\n}";
      expect(
        changes(
          [store],
          [
            store.replace(
              "    open(): void;",
              "    open(): void;\n    close(): void;",
            ),
          ],
        )[0],
      ).toMatchObject({ likelyBreaking: false });
    });
  });

  it("calls a removed member of an interface likely breaking", () => {
    const [change] = changes(
      [options],
      [options.replace("    size?: number;\n", "")],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: true });
  });

  it("calls a new member of an exported union likely breaking, on one line", () => {
    const [change] = changes(
      [mode],
      ['// @public\nexport type Mode = "light" | "dark" | "auto";'],
    );
    expect(change).toMatchObject({
      kind: "union-member-added",
      likelyBreaking: true,
    });
    expect(change.detail).toContain('"auto"');
  });

  it("reads a union that holds bars inside brackets and generics", () => {
    const before =
      "// @public\nexport type Handler = (value: string | number) => void | Promise<void> | Set<string | number>;";
    const after = before.replace(
      "Set<string | number>;",
      "Set<string | number> | null;",
    );
    expect(changes([before], [after])[0]).toMatchObject({
      kind: "union-member-added",
    });
  });

  it("names the members a union loses, and calls it likely breaking", () => {
    const before =
      '// @public\nexport type Mode = "light" | "dark" | "auto" | "night";';
    const [change] = changes([before], [mode]);
    expect(change).toMatchObject({
      kind: "union-member-removed",
      name: "Mode",
      likelyBreaking: true,
    });
    expect(change.detail).toBe('Mode lost "auto", "night".');
  });

  it("names a removed member of a replaced union, and says what it gained", () => {
    const [change] = changes(
      [mode],
      ['// @public\nexport type Mode = "light" | "night" | "auto";'],
    );
    expect(change).toMatchObject({
      kind: "union-member-removed",
      likelyBreaking: true,
    });
    expect(change.detail).toBe('Mode lost "dark", and gained "night", "auto".');
  });

  it("does not call a reordered union a change", () => {
    expect(
      changes([mode], ['// @public\nexport type Mode = "dark" | "light";']),
    ).toEqual([]);
  });

  it("shortens a long list of removed members and gives the total", () => {
    const keys = (count: number) =>
      Array.from({ length: count }, (_, index) => `    | "key.${index}"`).join(
        "\n",
      );
    const union = (count: number) =>
      `// @public\nexport type MessageKey =\n${keys(count)};`;
    const [change] = changes([union(30)], [union(5)]);
    expect(change.kind).toBe("union-member-removed");
    expect(change.detail).toContain('"key.5", "key.6"');
    expect(change.detail).toContain('"key.14"');
    expect(change.detail).not.toContain('"key.15"');
    expect(change.detail).toContain("15 more");
    expect(change.detail).toContain("25 members");
  });

  it("calls the loss of a member of an @internal union unsupported, not breaking", () => {
    const [change] = changes(
      ['// @internal\nexport type Mode = "light" | "dark";'],
      ['// @internal\nexport type Mode = "light" | "night";'],
    );
    expect(change).toMatchObject({
      kind: "union-member-removed",
      likelyBreaking: false,
    });
  });

  it("keeps a union that stops being a union as a plain change", () => {
    const [change] = changes(
      [mode],
      ['// @public\nexport type Mode = "light";'],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: true });
  });

  it("calls a new member of an enum likely breaking", () => {
    const before =
      "// @public\nexport enum Level {\n    High = 1,\n    Low = 0\n}";
    const after = before.replace("    Low = 0", "    Low = 0,\n    Mid = 2");
    expect(changes([before], [after])[0]).toMatchObject({
      kind: "enum-member-added",
      likelyBreaking: true,
    });
  });

  it("joins the blocks of one name, so removing an overload shows", () => {
    const one = "// @public\nexport function parse(text: string): string;";
    const two = "// @public\nexport function parse(text: number): number;";
    expect(changes([one, two], [one, two])).toEqual([]);
    const [change] = changes([one, two], [one]);
    expect(change).toMatchObject({
      kind: "changed",
      name: "parse",
      likelyBreaking: true,
    });
    expect(change.detail).toContain("text: number");
    expect(parseReport(report(one, two)).get("parse")?.lines).toHaveLength(2);
  });

  it("calls a gained @internal tag likely breaking", () => {
    const [change] = changes([greet], [greet.replace("@public", "@internal")]);
    expect(change).toMatchObject({
      kind: "gained-internal",
      likelyBreaking: true,
    });
  });

  it("does not call the removal of an @internal export likely breaking", () => {
    const internal = greet.replace("@public", "@internal");
    expect(changes([internal], [])).toEqual([
      expect.objectContaining({ kind: "removed", likelyBreaking: false }),
    ]);
  });

  it("does not call a changed @internal export likely breaking", () => {
    const internal = greet.replace("@public", "@internal");
    const [change] = changes(
      [internal],
      [internal.replace("name: string", "name: number")],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: false });
  });

  it("notes a gained @beta tag without calling it breaking", () => {
    const [change] = changes([greet], [greet.replace("@public", "@beta")]);
    expect(change).toMatchObject({
      kind: "gained-beta",
      likelyBreaking: false,
    });
  });

  it("ignores comment-only differences", () => {
    expect(changes([greet], [`// (undocumented)\n${greet}`])).toEqual([]);
  });

  it("treats a whole new report as additions and a whole removed one as removals", () => {
    expect(diffReports(null, report(greet))).toEqual([
      expect.objectContaining({ kind: "added", likelyBreaking: false }),
    ]);
    expect(diffReports(report(greet), null)).toEqual([
      expect.objectContaining({ kind: "removed", likelyBreaking: true }),
    ]);
  });

  it("sorts the changes by name", () => {
    const names = changes([], [mode, greet, options]).map(
      (change) => change.name,
    );
    expect(names).toEqual(["greet", "Mode", "Options"]);
  });
});

describe("compareApiReports", () => {
  function source(files: Record<string, string>) {
    return {
      list: (folder: string) =>
        Object.keys(files)
          .filter((file) => file.startsWith(`${folder}/`))
          .map((file) => file.slice(folder.length + 1)),
      read: (file: string) => files[file] ?? null,
    };
  }

  it("compares every package and entry point, and names them", () => {
    const before = source({
      "packages/core/api/index.api.md": report(greet),
      "packages/core/api/contracts.api.md": report(mode),
      "packages/theme/api/index.api.md": report(greet),
    });
    const after = source({
      "packages/core/api/index.api.md": report(greet),
      "packages/core/api/contracts.api.md": report(),
      "packages/theme/api/index.api.md": report(greet, mode),
      "packages/map/api/index.api.md": report(options),
    });
    expect(compareApiReports(before, after)).toEqual([
      expect.objectContaining({
        package: "@mapcairn/core",
        entry: "contracts",
        kind: "removed",
      }),
      expect.objectContaining({
        package: "@mapcairn/theme",
        entry: "index",
        kind: "added",
      }),
      expect.objectContaining({
        package: "@mapcairn/map",
        entry: "index",
        kind: "added",
      }),
    ]);
  });
});
